from pathlib import Path
import json,re,sys,datetime
R=Path(__file__).resolve().parents[2]
IDX={int(x['unit']):x for f in ['discovery-index.jsonl','discovery-index-02.jsonl'] for x in map(json.loads,(R/'_raw/communities'/f).read_text().splitlines())}
rows=[]
def add(unit,speaker,stage,typ,themes,quote,context,date=None,segment=None):
    item=IDX[unit];text=(R/item['raw_file']).read_text()
    assert quote in text,(unit,quote)
    assert len(context.split())<=25,(unit,context)
    sub=re.search(r'/r/([^/]+)/',item['url'])[1]
    if date is None:
        m=re.search(r'\[(?:Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday) ([A-Z][a-z]+ \d{2} \d{4})\]',text)
        date=datetime.datetime.strptime(m[1],'%B %d %Y').date().isoformat() if m else ''
    market={'BabyBumpsandBeyondAu':'AU','BeyondTheBumpUK':'UK','PregnancyUK':'UK','BabyBumpsCanada':'CA'}.get(sub,'unknown')
    country='AU' if unit==17 and 'Australia. Personal opinion.' in quote else ('FR' if unit==59 else 'unknown')
    rows.append(dict(id=f'aud01-{len(rows)+1:04d}',source='reddit-index-'+sub.lower(),url=item['url'],date=date,speaker=speaker,stage=stage,type=typ,themes=themes.split(),quote=quote,context=context,raw_file=item['raw_file'],source_class='community_index',evidence_kind='search_index_excerpt',country=country,community_market=market,segment=segment or '',index_unit_read_in_full=True,original_thread_read_in_full=False))

